import{_ as i,o as a,c as s,a2 as t}from"./chunks/framework.Dsf4_p3t.js";const u=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/contributing.md","filePath":"guide/contributing.md","lastUpdated":1786978364000}'),n={name:"guide/contributing.md"};function l(o,e,r,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Thanks for your interest in contributing to NeoFlux! This document outlines the coding standards and workflow expected for all pull requests.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before submitting a PR, make sure you have:</p><ul><li>A C++20-capable compiler (GCC 11+, Clang 14+, MSVC 2022)</li><li>CMake 3.20+</li><li>clang-tidy (for static analysis)</li><li>Git</li></ul><h2 id="coding-standards" tabindex="-1">Coding Standards <a class="header-anchor" href="#coding-standards" aria-label="Permalink to &quot;Coding Standards&quot;">​</a></h2><h3 id="c-standard" tabindex="-1">C++ Standard <a class="header-anchor" href="#c-standard" aria-label="Permalink to &quot;C++ Standard&quot;">​</a></h3><p>NeoFlux targets <strong>C++20</strong>. Use modern C++20 features where appropriate:</p><ul><li><code>std::string_view</code> for non-owning string parameters</li><li>Designated initializers for structs</li><li>Ranges and views (<code>std::views::filter</code>, <code>std::views::transform</code>)</li><li>Concepts and constraints</li><li><code>std::span</code> for array views</li><li>Coroutines (<code>Task&lt;void&gt;</code>) for async work</li></ul><p>Reference: <a href="https://en.cppreference.com/w/cpp/20" target="_blank" rel="noreferrer">C++20 on cppreference</a></p><h3 id="google-c-style-guide" tabindex="-1">Google C++ Style Guide <a class="header-anchor" href="#google-c-style-guide" aria-label="Permalink to &quot;Google C++ Style Guide&quot;">​</a></h3><p>NeoFlux follows the <a href="https://google.github.io/styleguide/cppguide.html" target="_blank" rel="noreferrer">Google C++ Style Guide</a>. Key points:</p><ul><li>Names: <code>PascalCase</code> for classes/structs, <code>snake_case</code> for functions/variables, <code>kConstantName</code> for compile-time constants, <code>trailing_underscore_</code> for member variables</li><li>Includes: project headers first, then third-party, then system</li><li>Comments: English only, Doxygen-style for public APIs</li><li>No <code>using namespace</code> in headers</li><li>Lines should be under 80 characters where practical</li></ul><h3 id="raii-and-smart-pointers" tabindex="-1">RAII and Smart Pointers <a class="header-anchor" href="#raii-and-smart-pointers" aria-label="Permalink to &quot;RAII and Smart Pointers&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Never use raw <code>new</code>/<code>delete</code> or raw owning pointers in new code.</p></div><ul><li>Use <code>std::unique_ptr</code> for exclusive ownership</li><li>Use <code>std::shared_ptr</code> for shared ownership (Widget tree uses this)</li><li>Use <code>std::weak_ptr</code> for non-owning observers (especially in coroutines)</li><li>Use <code>std::string_view</code> for non-owning string parameters</li><li>Use RAII wrappers for all resources (file handles, GPU contexts, etc.)</li></ul><p>Reference: <a href="https://en.cppreference.com/w/cpp/language/raii" target="_blank" rel="noreferrer">RAII on cppreference</a> Reference: <a href="https://en.cppreference.com/w/cpp/memory" target="_blank" rel="noreferrer">Smart pointers on cppreference</a></p><h3 id="header-only-declarations" tabindex="-1">Header-Only Declarations <a class="header-anchor" href="#header-only-declarations" aria-label="Permalink to &quot;Header-Only Declarations&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Headers (<code>.h</code>) must contain only declarations. All implementations go in <code>.cpp</code> files. Template classes use <code>.inc</code> files with explicit instantiation in <code>.cpp</code>.</p></div><p>This keeps compile times fast and hides implementation details.</p><h3 id="pure-ascii" tabindex="-1">Pure ASCII <a class="header-anchor" href="#pure-ascii" aria-label="Permalink to &quot;Pure ASCII&quot;">​</a></h3><p>All source code, comments, log messages, and string literals must be pure ASCII. No non-ASCII characters (including Chinese) are allowed in <code>.h</code>/<code>.cpp</code> files.</p><h2 id="static-analysis" tabindex="-1">Static Analysis <a class="header-anchor" href="#static-analysis" aria-label="Permalink to &quot;Static Analysis&quot;">​</a></h2><h3 id="clang-tidy" tabindex="-1">clang-tidy <a class="header-anchor" href="#clang-tidy" aria-label="Permalink to &quot;clang-tidy&quot;">​</a></h3><p>All PRs must pass clang-tidy with zero warnings. Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang-tidy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.cpp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> include/neoflux/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.h</span></span></code></pre></div><p>The project ships a <code>.clang-tidy</code> configuration. Common checks enforced:</p><ul><li><code>modernize-*</code> — modern C++ idioms</li><li><code>performance-*</code> — performance optimizations</li><li><code>readability-*</code> — code readability</li><li><code>bugprone-*</code> — common bug patterns</li><li><code>cppcoreguidelines-*</code> — C++ Core Guidelines</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If clang-tidy suggests a change that would harm readability or performance, document the reason in the PR and add a targeted <code>NOLINT</code> comment.</p></div><h3 id="compiler-warnings" tabindex="-1">Compiler Warnings <a class="header-anchor" href="#compiler-warnings" aria-label="Permalink to &quot;Compiler Warnings&quot;">​</a></h3><p>The build uses <code>-Wall -Wextra -Wpedantic -Werror</code>. All PRs must compile with zero warnings.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><ul><li>Add unit tests for new functionality under <code>tests/</code></li><li>Run the full test suite before submitting:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_BUILD_TESTS=ON</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ctest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-on-failure</span></span></code></pre></div><h2 id="pull-request-workflow" tabindex="-1">Pull Request Workflow <a class="header-anchor" href="#pull-request-workflow" aria-label="Permalink to &quot;Pull Request Workflow&quot;">​</a></h2><ol><li>Fork the repository and create a feature branch</li><li>Make your changes following the standards above</li><li>Run clang-tidy and fix all warnings</li><li>Build with <code>-Werror</code> and ensure zero warnings</li><li>Run the test suite</li><li>Submit a PR with a clear description of the change</li></ol><h2 id="commit-messages" tabindex="-1">Commit Messages <a class="header-anchor" href="#commit-messages" aria-label="Permalink to &quot;Commit Messages&quot;">​</a></h2><p>Use conventional commit format:</p><ul><li><code>feat:</code> — new feature</li><li><code>fix:</code> — bug fix</li><li><code>docs:</code> — documentation only</li><li><code>refactor:</code> — code change that neither fixes a bug nor adds a feature</li><li><code>perf:</code> — performance improvement</li><li><code>test:</code> — adding or updating tests</li><li><code>chore:</code> — build process, tooling, or maintenance</li></ul><h2 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h2><p>If you have questions about contributing, open an issue on GitHub.</p>`,41)])])}const g=i(n,[["render",l]]);export{u as __pageData,g as default};
